65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
68	
69	    private final ClinicService clinicService;
70	
71	    private final OwnerMapper ownerMapper;
72	
