28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be E.164 form: a leading '+' followed by 8 to 15 digits")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    @Email
54	    private String email;
55	
56	    @Column(name = "registration_date", columnDefinition = "DATE")
57	    private LocalDate registrationDate;
58	
59	    @Column(name = "customer_code")
60	    private String customerCode;
61	
62	    @Column(name = "household_id")
63	    private String householdId;
64	
65	    @Column(name = "namesake_count")
66	    private Integer namesakeCount;
67	
68	    @Column(name = "household_size")
69	    private Integer householdSize;
70	
71	    @Column(name = "postcode")
72	    private String postcode;
73	
74	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
75	    private Set<Pet> pets;
76	
77	    public String getAddress() {
78	        return this.address;
79	    }
80	
81	    public void setAddress(String address) {
82	        this.address = address;
83	    }
84	
85	    public String getCity() {
86	        return this.city;
87	    }
88	
89	    public void setCity(String city) {
90	        this.city = city;
91	    }
92	
93	    public String getTelephone() {
94	        return this.telephone;
95	    }
96	
97	    public void setTelephone(String telephone) {
98	        this.telephone = telephone;
99	    }
100	
101	    public String getEmail() {
102	        return this.email;
103	    }
104	
105	    /**
106	     * Stores the email lower-cased so it is persisted and returned in a canonical form. A
107	     * {@code null} value (email omitted) is preserved as {@code null}.
108	     */
109	    public void setEmail(String email) {
110	        this.email = email == null ? null : email.toLowerCase(Locale.ROOT);
111	    }
112	
113	    public LocalDate getRegistrationDate() {
114	        return this.registrationDate;
115	    }
116	
117	    public void setRegistrationDate(LocalDate registrationDate) {
118	        this.registrationDate = registrationDate;
119	    }
120	
121	    public String getCustomerCode() {
122	        return this.customerCode;
123	    }
124	
125	    public void setCustomerCode(String customerCode) {
126	        this.customerCode = customerCode;
127	    }
128	
129	    /**
130	     * The owner's membership number, formatted {@code <customerCode>-M<YY>} where {@code YY} is
131	     * the last two digits of the {@code registrationDate} year (e.g. {@code LON-SMI-0007-M26}).
132	     * Derived from the owner's own fields; {@code null} until both are assigned.
133	     */
134	    @Transient
135	    public String getMembershipNumber() {
136	        if (this.customerCode == null || this.registrationDate == null) {
137	            return null;
138	        }
139	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
140	    }
141	
142	    /**
143	     * The owner's membership level, a number from 1 to 3 derived from the owner's own fields as
144	     * captured at creation time. It starts at 1, gains 1 when an email is present, gains a further
145	     * 1 when the owner has no namesakes ({@code namesakeCount} is 0), and is capped at 3. Level 4
146	     * is reserved for tenure and is never produced here.
147	     */
148	    @Transient
149	    public Integer getMembershipLevel() {
150	        int level = 1;
151	        boolean hasEmail = this.email != null && !this.email.isBlank();
152	        if (hasEmail) {
153	            level++;
154	        }
155	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
156	        if (noNamesakes) {
157	            level++;
158	        }
159	        return Math.min(level, 3);
160	    }
161	
162	    /** City -> canonical region for the {@code locality} derivation. */
163	    private static final Map<String, String> CITY_REGION = Map.of(
164	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
165	
166	    /** Region -> inclusive 4-digit postcode range {low, high} for the {@code locality} derivation. */
167	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
168	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
169	
170	    /**
171	     * The owner's locality, derived by looking up the region by {@link #postcode} range first
172	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), and only falling back to the fixed
173	     * city-to-region table (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) when the postcode is
174	     * absent or in no known range. Returns {@code UNKNOWN} when neither source resolves a region.
175	     */
176	    @Transient
177	    public String getLocality() {
178	        String region = regionForPostcode(this.postcode);
179	        if (region != null) {
180	            return region;
181	        }
182	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
183	    }
184	
185	    /** Region whose postcode range contains the given postcode, or {@code null} when none does. */
186	    private static String regionForPostcode(String postcode) {
187	        if (postcode == null) {
188	            return null;
189	        }
190	        int value;
191	        try {
192	            value = Integer.parseInt(postcode.trim());
193	        }
194	        catch (NumberFormatException ex) {
195	            return null;
196	        }
197	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
198	            int[] range = entry.getValue();
199	            if (value >= range[0] && value <= range[1]) {
200	                return entry.getKey();
201	            }
202	        }
203	        return null;
204	    }
205	
206	    /**
207	     * The owner's identity key, the single derived value all duplicate detection is based on. It is
208	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}, where the telephone
209	     * is the stored E.164 value, the email is the stored lower-cased value (empty when absent) and
210	     * the household segment is the {@code householdId} (empty when the owner does not share a
211	     * household). Two owners are duplicates only when their whole identity keys are equal.
212	     */
213	    @Transient
214	    public String getIdentityKey() {
215	        String telephonePart = this.telephone == null ? "" : this.telephone;
216	        String emailPart = (this.email == null || this.email.isBlank()) ? "" : this.email;
217	        String householdPart = this.householdId == null ? "" : this.householdId;
218	        return telephonePart + "|" + emailPart + "|" + householdPart;
219	    }
220	
221	    public String getHouseholdId() {
222	        return this.householdId;
223	    }
224	
225	    public void setHouseholdId(String householdId) {
226	        this.householdId = householdId;
227	    }
228	
229	    public Integer getNamesakeCount() {
230	        return this.namesakeCount;
231	    }
232	
233	    public void setNamesakeCount(Integer namesakeCount) {
234	        this.namesakeCount = namesakeCount;
235	    }
236	
237	    public Integer getHouseholdSize() {
238	        return this.householdSize;
239	    }
240	
241	    public void setHouseholdSize(Integer householdSize) {
242	        this.householdSize = householdSize;
243	    }
244	
245	    public String getPostcode() {
246	        return this.postcode;
247	    }
248	
249	    public void setPostcode(String postcode) {
250	        this.postcode = postcode;
251	    }
252	
253	    protected Set<Pet> getPetsInternal() {
254	        if (this.pets == null) {
255	            this.pets = new HashSet<>();
256	        }
257	        return this.pets;
258	    }
259	
260	    protected void setPetsInternal(Set<Pet> pets) {
261	        this.pets = pets;
262	    }
263	
264	    public List<Pet> getPets() {
265	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
266	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
267	        return Collections.unmodifiableList(sortedPets);
268	    }
269	
270	    public void setPets(List<Pet> pets) {
271	        this.pets = new HashSet<>(pets);
272	    }
273	
274	    public void addPet(Pet pet) {
275	        getPetsInternal().add(pet);
276	        pet.setOwner(this);
277	    }
278	
279	    /**
280	     * Return the Pet with the given name, or null if none found for this Owner.
281	     *
282	     * @param name to test
283	     * @return true if pet name is already in use
284	     */
285	    public Pet getPet(String name) {
286	        return getPet(name, false);
287	    }
288	
289	    /**
290	     * Return the Pet with the given name, or null if none found for this Owner.
291	     *
292	     * @param name to test
293	     * @return true if pet name is already in use
294	     */
295	    public Pet getPet(String name, boolean ignoreNew) {
296	        name = name.toLowerCase();
297	        for (Pet pet : getPetsInternal()) {
298	            if (!ignoreNew || !pet.isNew()) {
299	                String compName = pet.getName();
300	                compName = compName.toLowerCase();
301	                if (compName.equals(name)) {
302	                    return pet;
303	                }
304	            }
305	        }
306	        return null;
307	    }
308	
309	    public Pet getPet(Integer petId) {
310	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
311	    }
312	
313	    @Override
314	    public String toString() {
315	        return new ToStringCreator(this)
316	
317	            .append("id", this.getId())
318	            .append("new", this.isNew())
319	            .append("lastName", this.getLastName())
320	            .append("firstName", this.getFirstName())
321	            .append("address", this.address)
322	            .append("city", this.city)
323	            .append("telephone", this.telephone)
324	            .append("email", this.email)
325	            .toString();
326	    }
327	}
